mapper.select:
		/*	설명 : 주차출석율조회 */
		/*
		CREATE INDEX ATNDLC_IDX02 ON TB_LMS_ATNDLC (SBJCT_ID, USER_ID);
		CREATE INDEX BYWKNO_USER_LRN_STS_IDX01 ON TB_LMS_BYWKNO_USER_LRN_STS (LCTR_WKNO_SCHDL_ID, USER_ID);
		*/
		WITH B AS (
		    SELECT 	USER_ID, LRN_STSCD
		    FROM 	TB_LMS_BYWKNO_USER_LRN_STS
		    WHERE 	LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
		)
		SELECT 	SUM( CASE WHEN B.LRN_STSCD IN ('CMPTN', 'LATE', 'STUDY') THEN 1 ELSE 0 END) AS ATND_CNT,
        		ROUND ( SUM ( CASE WHEN B.LRN_STSCD IN ('CMPTN', 'LATE', 'STUDY') THEN 1 ELSE 0 END) / NULLIF(COUNT(A.USER_ID), 0) * 100 , 2) AS ATND_RATE
		FROM 	TB_LMS_ATNDLC A
				LEFT 	JOIN B ON B.USER_ID = A.USER_ID
		WHERE 	A.SBJCT_ID = #{sbjctId}

	/*	설	명 	: 과목접속수강생수조회 	*/
 	SELECT	COUNT(DISTINCT LUA.USER_ID) AS SBJCT_CNTN_CNT
	FROM	TB_LMS_ATNDLC A
			JOIN TB_LMS_LOG_USER_ACTV LUA ON LUA.SBJCT_ID = A.SBJCT_ID
	    			AND LUA.ACTV_DATETIME >= ( SYSDATE - NUMTODSINTERVAL( 120, 'MINUTE' ) )
	WHERE 	1 = 1	AND A.SBJCT_ID = #{sbjctId}

	/*	설	명 	: 과목총수강생수조회 	*/
 	SELECT	COUNT(A.USER_ID) SBJCT_TOT_STD_CNT
	FROM	TB_LMS_ATNDLC A
	WHERE	1 = 1 	AND A.SBJCT_ID = #{sbjctId}

	/*	설	명 	: 접속수강생수조회 	*/
 	SELECT	COUNT(DISTINCT LUA.USER_ID) AS CNTN_CNT
	FROM	TB_LMS_SBJCT_ADM ADM
			JOIN TB_LMS_LOG_USER_ACTV LUA ON LUA.SBJCT_ID = ADM.SBJCT_ID
	    			AND LUA.ACTV_DATETIME >= ( SYSDATE - NUMTODSINTERVAL( 120, 'MINUTE' ) )
	WHERE ADM.USER_ID = #{userId}

	/*	설	명 	: 총수강생수조회 	*/
 	SELECT	COUNT(A.USER_ID) TOT_STD_CNT
	FROM	TB_LMS_SBJCT_ADM ADM
			JOIN 	TB_LMS_SBJCT S ON ADM.SBJCT_ID = S.SBJCT_ID AND S.DELYN = 'N'
			JOIN 	TB_LMS_ATNDLC A ON S.SBJCT_ID = A.SBJCT_ID
	WHERE	1 = 1 	AND ADM.USER_ID = #{userId}

/* 설 명 : 기관별부서별과목조회 */ SELECT SBJCT.*
, ORG.ORG_ID
, DEPT.DEPT_ID , DEPT.DEPTNM
FROM TB_LMS_SBJCT SBJCT
JOIN TB_LMS_SMSTR_CHRT SC ON SBJCT.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON SC.ORG_ID = ORG.ORG_ID
JOIN TB_LMS_DEPT DEPT ON SBJCT.DEPT_ID = DEPT.DEPT_ID
WHERE SBJCT.DELYN = 'N'
AND ORG.ORG_ID = #{orgId}
AND DEPT.DEPT_ID = #{deptId}

/* 설 명 : 교수과목요약목록조회
필요인덱스 CREATE INDEX IDX_BBS_01 ON TB_LMS_BBS (SBJCT_ID, BBS_ID); CREATE INDEX IDX_BBS_02 ON TB_LMS_BBS (BBS_ID, DELYN); CREATE INDEX IDX_BBS_ATCL_01 ON TB_LMS_BBS_ATCL (BBS_ID, ATCL_ID); CREATE INDEX IDX_ATNDLC_01 ON TB_LMS_ATNDLC (SBJCT_ID); CREATE INDEX IDX_ASMT_01 ON TB_LMS_ASMT (SBJCT_ID); CREATE INDEX IDX_DSCS_01 ON TB_LMS_DSCS (SBJCT_ID); CREATE INDEX IDX_SMNR_01 ON TB_LMS_SMNR (SBJCT_ID); CREATE INDEX IDX_EXAM_BSC_01 ON TB_LMS_EXAM_BSC (SBJCT_ID); CREATE INDEX IDX_SRVY_01 ON TB_LMS_SRVY (SBJCT_ID);
CREATE INDEX IDX_BBS_QNA_09 ON TB_LMS_BBS(BBS_TYCD, SBJCT_ID, DELYN); CREATE INDEX IDX_BBS_ATCL_09 ON TB_LMS_BBS_ATCL(BBS_ID, DELYN, UP_ATCL_ID); CREATE INDEX IDX_EXAM_BSC_09 ON TB_LMS_EXAM_BSC(SBJCT_ID, DELYN, USEYN); CREATE INDEX IDX_EXAM_DTL_09 ON TB_LMS_EXAM_DTL(EXAM_BSC_ID, DELYN, USEYN); */ SELECT SA.SBJCT_ID SBJCT_ID , SA.SBJCT_ADM_TYCD , S.SBJCTNM , S.CRDTS , U.USERNM, U.USER_ID , O.ORGNM , O.ORG_SHRTNM , O.ORG_TYCD , O.ORG_ID , SA2.USER_ID TUT_USER_ID, U2.USERNM TUT_USERNM , EXAM.MID_EXAM_SDTTM, EXAM.MID_EXAM_MNTS, EXAM.LST_EXAM_SDTTM, EXAM.LST_EXAM_MNTS , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_ATNDLC AA WHERE AA.SBJCT_ID = SA.SBJCT_ID ) AS ATNDLC_CNT , ( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'NTC' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD IR WHERE IR.ATCL_ID = ATCL.ATCL_ID AND IR.VWER_ID = #{userId} ) WHERE BBS.SBJCT_ID = SA.SBJCT_ID ) AS NTC_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = SA.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'NTC' AND ROWNUM = 1 ) AS NTC_BBS_ID ,( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND ATCL.DELYN = 'N' AND ATCL.UP_ATCL_ID IS NULL WHERE BBS.SBJCT_ID = SA.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'QNA' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL R WHERE R.UP_ATCL_ID = ATCL.ATCL_ID AND R.DELYN = 'N' ) ) AS QNA_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = SA.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'QNA' AND ROWNUM = 1 ) AS QNA_BBS_ID ,( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND ATCL.DELYN = 'N' AND ATCL.UP_ATCL_ID IS NULL WHERE BBS.SBJCT_ID = SA.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = '1ON1' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL R WHERE R.UP_ATCL_ID = ATCL.ATCL_ID AND R.DELYN = 'N' ) ) AS ONEONONE_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = SA.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = '1ON1' AND ROWNUM = 1 ) AS ONEONONE_BBS_ID ,( SELECT COUNT(ASMT.SBJCT_ID) FROM TB_LMS_ASMT ASMT WHERE ASMT.SBJCT_ID = S.SBJCT_ID AND ASMT.DELYN = 'N' ) AS ASMT_CNT , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_DSCS AA WHERE AA.SBJCT_ID = SA.SBJCT_ID AND DELYN = 'N' AND DSCS_GBNCD NOT IN ('DSCS_SBST_EXAM_MID','DSCS_SBST_EXAM_LST') ) AS DSCS_CNT , ( SELECT COUNT(SMNR.SBJCT_ID) FROM TB_LMS_SMNR SMNR WHERE SMNR.SBJCT_ID = SA.SBJCT_ID AND SMNR.DELYN = 'N' AND SMNR.RGTR_ID = #{userId} AND UP_SMNR_ID IS NULL ) AS SMNR_CNT ,( SELECT COUNT(SRVY.SBJCT_ID) FROM TB_LMS_SRVY SRVY WHERE SRVY.SBJCT_ID = SA.SBJCT_ID AND SRVY.DELYN = 'N' AND SRVY.RGTR_ID = #{userId} AND SRVY.UP_SRVY_ID IS NULL ) AS SRVY_CNT , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_EXAM_BSC BSC WHERE BSC.SBJCT_ID = SA.SBJCT_ID AND BSC.DELYN = 'N' AND BSC.USEYN='Y' AND ( BSC.EXAM_TYCD = 'QUIZ' OR BSC.EXAM_GBNCD = 'QUIZ' ) ) AS QUIZ_CNT , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_EXAM_BSC AA WHERE AA.SBJCT_ID = SA.SBJCT_ID AND DELYN='N' AND USEYN='Y' AND EXAM_TYCD = 'EXAM' ) AS EXAM_CNT FROM TB_LMS_SBJCT_ADM SA JOIN TB_LMS_SBJCT S ON SA.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
AND SC.SMSTR_CHRT_ID = #{smstrChrtId}
AND SC.NOW_SMSTRYN = 'Y'
JOIN TB_LMS_USER U ON U.USER_ID = SA.USER_ID JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID LEFT JOIN TB_LMS_SBJCT_ADM SA2 ON SA.SBJCT_ID = SA2.SBJCT_ID AND SA2.SBJCT_ADM_TYCD = 'TUT' AND SA2.SBJCT_ADM_SEQNO = 1 LEFT JOIN TB_LMS_USER U2 ON U2.USER_ID = SA2.USER_ID LEFT JOIN ( SELECT SO.SBJCT_ID , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_MID' THEN ED.EXAM_PSBL_SDTTM END) AS MID_EXAM_SDTTM , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_MID' THEN ED.EXAM_MNTS END) AS MID_EXAM_MNTS , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_LST' THEN ED.EXAM_PSBL_SDTTM END) AS LST_EXAM_SDTTM , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_LST' THEN ED.EXAM_MNTS END) AS LST_EXAM_MNTS FROM TB_LMS_SBJCT SO JOIN TB_LMS_EXAM_BSC EB ON EB.SBJCT_ID = SO.SBJCT_ID AND EB.DELYN = 'N' AND EB.USEYN = 'Y' AND ( EB.EXAM_GBNCD = 'EXAM_MID' OR EB.EXAM_GBNCD = 'EXAM_LST') JOIN TB_LMS_EXAM_DTL ED ON EB.EXAM_BSC_ID = ED.EXAM_BSC_ID AND ED.DELYN = 'N' AND ED.USEYN = 'Y' WHERE 1 = 1 GROUP BY SO.SBJCT_ID ) EXAM ON SA.SBJCT_ID = EXAM.SBJCT_ID WHERE 1 = 1 AND SA.USER_ID = #{userId} ORDER BY O.ORGNM ASC, S.SBJCTNM ASC

/* 설 명 : 학생과목요약목록조회
필요인덱스 [교수과목요약목록조회와 공통] CREATE INDEX IDX_BBS_01 ON TB_LMS_BBS (SBJCT_ID, BBS_ID); CREATE INDEX IDX_BBS_02 ON TB_LMS_BBS (BBS_ID, DELYN); CREATE INDEX IDX_BBS_ATCL_01 ON TB_LMS_BBS_ATCL (BBS_ID, ATCL_ID); CREATE INDEX IDX_ATNDLC_01 ON TB_LMS_ATNDLC (SBJCT_ID); CREATE INDEX IDX_ASMT_01 ON TB_LMS_ASMT (SBJCT_ID); CREATE INDEX IDX_DSCS_01 ON TB_LMS_DSCS (SBJCT_ID); CREATE INDEX IDX_SMNR_01 ON TB_LMS_SMNR (SBJCT_ID); CREATE INDEX IDX_EXAM_BSC_01 ON TB_LMS_EXAM_BSC (SBJCT_ID); CREATE INDEX IDX_SRVY_01 ON TB_LMS_SRVY (SBJCT_ID);
CREATE INDEX IDX_BBS_QNA_09 ON TB_LMS_BBS(BBS_TYCD, SBJCT_ID, DELYN); CREATE INDEX IDX_BBS_ATCL_09 ON TB_LMS_BBS_ATCL(BBS_ID, DELYN, UP_ATCL_ID); CREATE INDEX IDX_EXAM_BSC_09 ON TB_LMS_EXAM_BSC(SBJCT_ID, DELYN, USEYN); CREATE INDEX IDX_EXAM_DTL_09 ON TB_LMS_EXAM_DTL(EXAM_BSC_ID, DELYN, USEYN);
필요인덱스 [학생과목요약목록조회] */ SELECT S.SBJCT_ID SBJCT_ID , SA2.SBJCT_ADM_TYCD , S.SBJCTNM , S.CRDTS , U.USERNM, U.USER_ID , O.ORGNM , O.ORG_TYCD , O.ORG_ID , O.ORG_SHRTNM , SA2.USER_ID TUT_USER_ID, U2.USERNM TUT_USERNM , EXAM.MID_EXAM_SDTTM, EXAM.MID_EXAM_MNTS, EXAM.LST_EXAM_SDTTM, EXAM.LST_EXAM_MNTS , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_ATNDLC AA WHERE AA.SBJCT_ID = S.SBJCT_ID ) AS ATNDLC_CNT , ( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'NTC' AND ATCL.DELYN ='N' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD IR WHERE IR.ATCL_ID = ATCL.ATCL_ID AND IR.VWER_ID = #{userId} ) WHERE BBS.SBJCT_ID = S.SBJCT_ID ) AS NTC_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = S.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'NTC' AND ROWNUM = 1 ) AS NTC_BBS_ID ,( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND ATCL.DELYN = 'N' AND ATCL.UP_ATCL_ID IS NULL WHERE BBS.SBJCT_ID = S.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'QNA' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL R WHERE R.UP_ATCL_ID = ATCL.ATCL_ID AND R.DELYN = 'N' ) ) AS QNA_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = S.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = 'QNA' AND ROWNUM = 1 ) AS QNA_BBS_ID ,( SELECT COUNT(ATCL.ATCL_ID) FROM TB_LMS_BBS BBS JOIN TB_LMS_BBS_ATCL ATCL ON BBS.BBS_ID = ATCL.BBS_ID AND ATCL.DELYN = 'N' AND ATCL.UP_ATCL_ID IS NULL WHERE BBS.SBJCT_ID = S.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = '1ON1' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL R WHERE R.UP_ATCL_ID = ATCL.ATCL_ID AND R.DELYN = 'N' ) ) AS ONEONONE_CNT , ( SELECT BBS_ID FROM TB_LMS_BBS BBS WHERE BBS.SBJCT_ID = S.SBJCT_ID AND BBS.DELYN = 'N' AND BBS.BBS_TYCD = '1ON1' AND ROWNUM = 1 ) AS ONEONONE_BBS_ID ,( SELECT COUNT(SBJCT_ID) FROM TB_LMS_ASMT ASMT JOIN TB_LMS_ASMT_SBMSN_TRGT TRGT ON TRGT.ASMT_ID = ASMT.ASMT_ID AND TRGT.USER_ID = #{userId} WHERE ASMT.SBJCT_ID = S.SBJCT_ID AND ASMT.DELYN = 'N' ) AS ASMT_CNT , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_DSCS AA WHERE AA.SBJCT_ID = S.SBJCT_ID AND DELYN = 'N' /* AND DSCS_GBNCD NOT IN ('DSCS_SBST_EXAM_MID','DSCS_SBST_EXAM_LST') */ ) AS DSCS_CNT , ( SELECT COUNT(SBJCT_ID) FROM TB_LMS_SMNR AA JOIN TB_LMS_SMNR_TRGTR TLST ON AA.SMNR_ID = TLST.SMNR_ID AND TLST.USER_ID = #{userId} WHERE AA.SBJCT_ID = S.SBJCT_ID AND AA.DELYN = 'N' ) AS SMNR_CNT ,( SELECT COUNT(SBJCT_ID) FROM TB_LMS_SRVY SRVY JOIN TB_LMS_SRVY_TRGT TLST ON SRVY.SRVY_ID = TLST.SRVY_ID JOIN TB_LMS_TEAM TLT ON TLST.TEAM_ID = TLT.TEAM_ID JOIN TB_LMS_TEAM_MBR TLTM ON TLT.TEAM_ID = TLTM.TEAM_ID AND TLTM.USER_ID = #{userId} WHERE SRVY.SBJCT_ID = S.SBJCT_ID AND SRVY.DELYN = 'N' ) AS SRVY_CNT , ( SELECT COUNT(BSC.SBJCT_ID) FROM TB_LMS_EXAM_BSC BSC JOIN TB_LMS_EXAM_DTL DTL ON BSC.EXAM_BSC_ID = DTL.EXAM_BSC_ID AND DTL.DELYN = 'N' JOIN TB_LMS_EXAM_TRGTR TRGTR ON DTL.EXAM_DTL_ID = TRGTR.EXAM_DTL_ID JOIN TB_LMS_TEAM TLT ON TRGTR.TEAM_ID = TLT.TEAM_ID JOIN TB_LMS_TEAM_MBR TLTM ON TLT.TEAM_ID = TLTM.TEAM_ID AND TLTM.USER_ID = #{userId} WHERE BSC.SBJCT_ID = S.SBJCT_ID AND BSC.USEYN='Y' AND BSC.DELYN='N' AND ( BSC.EXAM_TYCD = 'QUIZ' OR BSC.EXAM_GBNCD = 'QUIZ' ) ) AS QUIZ_CNT , ( SELECT COUNT(BSC.SBJCT_ID) FROM TB_LMS_EXAM_BSC BSC JOIN TB_LMS_EXAM_DTL DTL ON BSC.EXAM_BSC_ID = DTL.EXAM_BSC_ID AND DTL.DELYN = 'N' JOIN TB_LMS_EXAM_TRGTR TRGTR ON DTL.EXAM_DTL_ID = TRGTR.EXAM_DTL_ID JOIN TB_LMS_TEAM TLT ON TRGTR.TEAM_ID = TLT.TEAM_ID JOIN TB_LMS_TEAM_MBR TLTM ON TLT.TEAM_ID = TLTM.TEAM_ID AND TLTM.USER_ID = #{userId} WHERE BSC.SBJCT_ID = S.SBJCT_ID AND BSC.USEYN='Y' AND BSC.DELYN='N' AND ( BSC.EXAM_TYCD = 'EXAM') ) AS EXAM_CNT FROM TB_LMS_ATNDLC ATNDLC JOIN TB_LMS_SBJCT S ON ATNDLC.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON S.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID
AND SC.SMSTR_CHRT_ID = #{smstrChrtId}
AND SC.NOW_SMSTRYN = 'Y'
JOIN TB_LMS_USER U ON U.USER_ID = ATNDLC.USER_ID JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID LEFT JOIN TB_LMS_SBJCT_ADM SA2 ON S.SBJCT_ID = SA2.SBJCT_ID AND SA2.SBJCT_ADM_TYCD = 'TUT' AND SA2.SBJCT_ADM_SEQNO = 1 LEFT JOIN TB_LMS_USER U2 ON U2.USER_ID = SA2.USER_ID LEFT JOIN ( SELECT SO.SBJCT_ID , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_MID' THEN ED.EXAM_PSBL_SDTTM END) AS MID_EXAM_SDTTM , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_MID' THEN ED.EXAM_MNTS END) AS MID_EXAM_MNTS , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_LST' THEN ED.EXAM_PSBL_SDTTM END) AS LST_EXAM_SDTTM , MAX(CASE WHEN EB.EXAM_GBNCD = 'EXAM_LST' THEN ED.EXAM_MNTS END) AS LST_EXAM_MNTS FROM TB_LMS_SBJCT SO JOIN TB_LMS_EXAM_BSC EB ON EB.SBJCT_ID = SO.SBJCT_ID AND EB.DELYN = 'N' AND EB.USEYN = 'Y' AND ( EB.EXAM_GBNCD = 'EXAM_MID' OR EB.EXAM_GBNCD = 'EXAM_LST') JOIN TB_LMS_EXAM_DTL ED ON EB.EXAM_BSC_ID = ED.EXAM_BSC_ID AND ED.DELYN = 'N' AND ED.USEYN = 'Y' WHERE 1 = 1 GROUP BY SO.SBJCT_ID ) EXAM ON ATNDLC.SBJCT_ID = EXAM.SBJCT_ID WHERE ATNDLC.USER_ID = #{userId} ORDER BY O.ORGNM ASC, S.SBJCTNM ASC

	/* 설  명 : 학생혹은교수수조회*/
 	SELECT COUNT(*)
	FROM (
	    SELECT	1
	    FROM 	TB_LMS_ATNDLC WHERE 1 = 1

		        AND USER_ID IN #{id}

	    	AND SBJCT_ID = #{sbjctId}
	    UNION ALL
	    SELECT 	1
	    FROM 	TB_LMS_SBJCT_ADM WHERE 1 = 1

		        AND USER_ID IN #{id}

			AND SBJCT_ID = #{sbjctId}
	)

/* 설명 : 사용자 운영/수강 과목 기관 목록 조회 ID : SubjectDAO.selectUserSubjectOrgList */ SELECT * FROM ( /* 교수 운영과목 기관 */ SELECT O.ORG_ID , O.ORGNM , 'PROF' AS USER_TYCD , A.SBJCT_ADM_TYCD , A.USER_ID FROM TB_LMS_SBJCT S JOIN TB_LMS_SBJCT_ADM A ON A.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID WHERE 1=1 AND S.USEYN = 'Y' AND S.DELYN = 'N'
AND A.USER_ID = #{userId}
AND 1=2
GROUP BY O.ORG_ID, O.ORGNM, A.SBJCT_ADM_TYCD, A.USER_ID UNION ALL /* 학생 수강과목 기관 */ SELECT O.ORG_ID , O.ORGNM , 'STDNT' AS USER_TYCD , 'STDNT' AS SBJCT_ADM_TYCD , A.USER_ID AS USER_ID FROM TB_LMS_ATNDLC A JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON S.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON SC.ORG_ID = O.ORG_ID WHERE 1=1
AND A.USER_ID = #{userId}
AND 1=2
GROUP BY O.ORG_ID, O.ORGNM, A.USER_ID ) X ORDER BY USER_TYCD, ORGNM

/* 설 명 : 사용자별과목조회 */ SELECT ORG_ID, ORGNM, SBJCT_ID, SBJCTNM, USER_TYCD FROM ( SELECT O.ORG_ID, O.ORGNM, S.SBJCT_ID, S.SBJCTNM, 'PROF' AS USER_TYCD FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT SC ON S.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON SC.ORG_ID = O.ORG_ID WHERE 1 = 1
AND S.PROF_ID IN
#{id}
AND 1 = 2 /* 리스트가 비어있을 경우 조회를 방지하기 위한 조건 */
UNION ALL SELECT O.ORG_ID, O.ORGNM, S.SBJCT_ID, S.SBJCTNM, 'STDNT' AS USER_TYCD FROM TB_LMS_ATNDLC A JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON S.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON SC.ORG_ID = O.ORG_ID WHERE 1 = 1
AND A.USER_ID IN
#{id}
AND 1 = 2
)

/* 설명 : 사용자 운영/수강과목 학기 목록 조회 ID : SubjectDAO.selectUserSemesterList */ SELECT * FROM ( /* 교수 운영과목 학기 */ SELECT SC.SMSTR_CHRT_ID , SC.SMSTR_CHRTNM , SC.DGRS_YR , SC.DGRS_SMSTR_CHRT , SC.NOW_SMSTRYN , O.ORG_ID , O.ORG_SHRTNM , (CASE A.SBJCT_ADM_TYCD WHEN 'COPROF' THEN 'PROF' ELSE A.SBJCT_ADM_TYCD END) AS USER_TYCD FROM TB_LMS_SBJCT S JOIN TB_LMS_SBJCT_ADM A ON A.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID WHERE 1=1 AND S.USEYN = 'Y' AND S.DELYN = 'N'
AND A.USER_ID = #{userId}
AND 1=2
AND SC.ORG_ID = #{orgId}
GROUP BY SC.SMSTR_CHRT_ID, SC.SMSTR_CHRTNM, SC.DGRS_YR, SC.DGRS_SMSTR_CHRT, SC.NOW_SMSTRYN, O.ORG_ID, O.ORG_SHRTNM, (CASE A.SBJCT_ADM_TYCD WHEN 'COPROF' THEN 'PROF' ELSE A.SBJCT_ADM_TYCD END) UNION ALL /* 학생 수강과목 학기 */ SELECT SC.SMSTR_CHRT_ID , SC.SMSTR_CHRTNM , SC.DGRS_YR , SC.DGRS_SMSTR_CHRT , SC.NOW_SMSTRYN , O.ORG_ID , O.ORG_SHRTNM , 'STDNT' AS USER_TYCD FROM TB_LMS_ATNDLC A JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON S.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID JOIN TB_LMS_ORG O ON O.ORG_ID = SC.ORG_ID WHERE 1=1
AND A.USER_ID = #{userId}
AND 1=2
AND SC.ORG_ID = #{orgId}
GROUP BY SC.SMSTR_CHRT_ID, SC.SMSTR_CHRTNM, SC.DGRS_YR, SC.DGRS_SMSTR_CHRT, SC.NOW_SMSTRYN, O.ORG_ID, O.ORG_SHRTNM ) X ORDER BY DGRS_YR DESC, DGRS_SMSTR_CHRT DESC
